insert into public.posts (slug, title, summary, date, category, formato, image, image_alt, onde, tags, blocos, rascunho)
values (
  $inv$jogos-anos-2000-nostalgia$inv$,
  $inv$7 jogos dos anos 2000 que viraram memória afetiva de uma geração$inv$,
  $inv$Do PS2 ao Game Boy Advance, estes jogos fizeram parte de tardes inteiras, disputas com amigos e memórias que continuam vivas até hoje.$inv$,
  $inv$2026-10-26T12:38:10.633Z$inv$::timestamptz,
  $inv$games$inv$,
  $inv$lista$inv$,
  $inv$/uploads/2026/dp7soxmseext9mfnm8vfot3trbc-il4jshg7vbdxvilgj6b6it-pzfkole6gtjj-sub0tgoppelpg70h-mvp92l6ydbz.webp$inv$,
  $inv$$inv$,
  array[$inv$em-alta$inv$]::text[],
  array[$inv$nostalgia$inv$, $inv$games$inv$, $inv$playstation 2$inv$, $inv$gamecube$inv$, $inv$game boy advance$inv$, $inv$gta$inv$, $inv$the sims$inv$, $inv$need for speed$inv$]::text[],
  $inv$[{"tipo": "texto", "texto": "Se você cresceu jogando nos anos 2000, provavelmente existe pelo menos um jogo capaz de desbloquear uma memória inteira com poucos segundos de gameplay.\nPode ser o som de inicialização do PlayStation 2, uma música tocando enquanto você modificava um carro, horas escolhendo móveis para uma casa virtual ou aquela batalha de Pokémon que parecia impossível quando você era criança.\nFoi uma década cheia de jogos que não ficaram apenas na memória por serem bons. Eles fizeram parte da rotina de muita gente.\nPor isso, separamos sete jogos dos anos 2000 que ajudam a explicar por que aquela geração ainda fala deles com tanto carinho."}, {"tipo": "subtitulo", "texto": "Grand Theft Auto: San Andreas"}, {"tipo": "imagem", "src": "/uploads/2026/grand-theft-auto-san-andreas-mvp99x2wxm9.webp", "largura": "normal"}, {"tipo": "texto", "texto": "Para muita gente, poucos jogos representam tanto os anos 2000 quanto Grand Theft Auto: San Andreas.\n\nA aventura de CJ por Los Santos, San Fierro e Las Venturas parecia gigantesca para a época. Mas não eram apenas as missões que faziam o jogo especial.\n\nTinha academia, bicicleta, carros, roupas, barbearia, restaurantes, territórios de gangues e dezenas de pequenas coisas para descobrir.\n\nEra o tipo de jogo em que você ligava o videogame pensando em fazer uma missão e terminava duas horas depois fugindo da polícia depois de causar confusão pela cidade.\n\nPara muita gente, San Andreas não era apenas um jogo. Era praticamente um lugar para onde você voltava depois da escola."}, {"tipo": "subtitulo", "texto": "The Sims 2"}, {"tipo": "imagem", "src": "/uploads/2026/les-30-jeux-pc-les-plus-populaires-mvp9aizycit.webp", "largura": "normal"}, {"tipo": "texto", "texto": "Antes de passarmos horas personalizando personagens em praticamente qualquer jogo moderno, The Sims 2 já deixava jogadores obcecados em criar famílias, construir casas e transformar uma pequena decisão em um desastre completo.\n\nA graça estava justamente nisso.\n\nVocê podia tentar criar a família perfeita ou simplesmente remover a escada da piscina e observar o caos.\n\nO jogo transformou situações completamente comuns, como conseguir emprego, fazer amigos, se apaixonar, ter filhos e comprar móveis, em algo estranhamente viciante.\n\nE provavelmente também foi responsável por ensinar uma geração inteira que decorar uma casa virtual pode consumir muito mais tempo do que deveria.\n\nSe você passava mais tempo construindo a casa do que realmente jogando com a família, você definitivamente não estava sozinho."}, {"tipo": "subtitulo", "texto": "Need for Speed: Underground 2"}, {"tipo": "imagem", "src": "/uploads/2026/my-childhood-was-a-gaming-heaven-by-imran-ali-mr-plan-publication-medium-mvp9awnil65.webp", "largura": "normal"}, {"tipo": "texto", "texto": "Neon embaixo do carro. Rodas enormes. Adesivos. Spoilers. Música alta.\n\nNeed for Speed: Underground 2 conseguiu transformar personalização de carros em uma das coisas mais importantes da vida de uma criança que nem idade para dirigir tinha.\n\nO mundo de Bayview dava uma sensação de liberdade enorme, enquanto o sistema de customização fazia cada carro parecer realmente seu.\n\nÀs vezes, vencer a corrida nem parecia ser a parte mais importante.\n\nO objetivo verdadeiro era deixar o carro o mais exagerado possível.\n\nE olhando para algumas das modificações que fazíamos naquela época, talvez seja melhor que ninguém tenha nos dado dinheiro suficiente para personalizar um carro de verdade."}, {"tipo": "subtitulo", "texto": "Pokémon Ruby & Sapphire"}, {"tipo": "imagem", "src": "/uploads/2026/bulbapedia-bulbapedia-on-x-mvp9batcy1v.webp", "largura": "normal"}, {"tipo": "texto", "texto": "Para quem teve um Game Boy Advance, ou conheceu alguém que tinha, Pokémon Ruby & Sapphire representam uma fase inesquecível da franquia.\n\nHoenn trouxe uma nova região para explorar, dezenas de novos Pokémon e dois lendários que se tornariam alguns dos mais conhecidos da série: Groudon e Kyogre.\n\nEscolher entre Treecko, Torchic e Mudkip também era uma decisão muito mais séria do que qualquer criança deveria precisar tomar.\n\nE, naturalmente, cada pessoa tinha certeza absoluta de que sua escolha era a correta.\n\nAlgumas amizades sobreviveram à escolha entre Ruby e Sapphire. Outras talvez nunca tenham se recuperado."}, {"tipo": "subtitulo", "texto": "God of War"}, {"tipo": "imagem", "src": "/uploads/2026/the-evolution-of-kratos-posture-max-frequency-mvp9busphfh.webp", "largura": "normal"}, {"tipo": "texto", "texto": "Antes de Kratos virar o pai cansado e extremamente sério que conhecemos nos jogos mais recentes, existia uma versão consideravelmente mais irritada dele no PlayStation 2.\n\nO primeiro God of War colocou o guerreiro espartano contra criaturas e deuses da mitologia grega em uma aventura que parecia gigantesca.\n\nCombates rápidos, chefes enormes e cenas que pareciam impossíveis para um videogame daquela geração ajudaram a transformar Kratos em um dos personagens mais reconhecíveis da história do PlayStation."}, {"tipo": "subtitulo", "texto": "Super Mario Sunshine"}, {"tipo": "imagem", "src": "/uploads/2026/2002-super-mario-sunshine-nintendo-gamecube-print-ad-poster-official-promo-art-e-mvp9c793xf9.webp", "largura": "normal"}, {"tipo": "texto", "texto": "O GameCube também teve seu próprio Mario inesquecível.\n\nEm Super Mario Sunshine, Mario abandona por um momento os campos tradicionais do Reino dos Cogumelos e vai parar na ensolarada Ilha Delfino.\n\nSó que suas férias não duram muito.\n\nEquipado com o FLUDD, uma espécie de mochila que dispara água, Mario precisa limpar a ilha enquanto enfrenta plataformas, inimigos e uma quantidade suspeitamente grande de sujeira.\n\nO resultado é um dos jogos mais diferentes da fase clássica 3D de Mario e também um daqueles títulos que imediatamente lembram o GameCube."}, {"tipo": "subtitulo", "texto": "Guitar Hero"}, {"tipo": "imagem", "src": "/uploads/2026/guitar-hero-playstation-2-walmart-com-mvp9cmqj29o.webp", "largura": "normal"}, {"tipo": "texto", "texto": "Talvez poucas coisas tenham sido tão anos 2000 quanto segurar uma guitarra de plástico no meio da sala e agir como se estivesse tocando para um estádio lotado.\n\nGuitar Hero transformou isso em uma experiência praticamente obrigatória em festas, locadoras e casas de amigos.\n\nNão precisava saber tocar guitarra.\n\nNão precisava sequer ter coordenação suficiente para apertar cinco botões coloridos.\n\nO importante era tentar.\n\nE quando você finalmente conseguia passar aquela música que parecia impossível, por alguns minutos era fácil acreditar que realmente tinha virado uma estrela do rock."}]$inv$::jsonb,
  false
)
on conflict (slug) do nothing;
